import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Vectorized matrix-vector multiplication kernel.
// Computes C[m] = sum_k A[m, k] * B[k]  for a matrix A of shape (M, K)
// and a vector B of shape (K, 1). One CUDA block handles one row of A.
// Uses CuTe tensors for indexing, and CuTe's recast<> to reinterpret the
// contiguous K-dimension as float4 vectors for coalesced, wide loads.
template <typename T>
__global__ void matvec_kernel_vec4(
    const T* __restrict__ A,
    const T* __restrict__ B,
    T* __restrict__ C,
    int M, int K)
{
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    for (int m = blockIdx.x; m < M; m += gridDim.x) {
        // CuTe views over the current row of A and over B (both length K, stride 1)
        Tensor gA = make_tensor(make_gmem_ptr(A + (int64_t)m * K), make_shape(K), make_stride(Int<1>{}));
        Tensor gB = make_tensor(make_gmem_ptr(B), make_shape(K), make_stride(Int<1>{}));
        // Reinterpret as float4 vectors (assumes K % 4 == 0)
        Tensor gA4 = recast<float4>(gA);
        Tensor gB4 = recast<float4>(gB);
        int K4 = size(gA4);
        // A is read exactly once per row (no reuse across blocks) -> use streaming
        // (non-caching) loads to avoid polluting L1/L2 with data that won't be reused.
        // B is reused across every row processed by every block -> use read-only
        // cache (__ldg) loads so it stays resident in cache for reuse.
        const float4* __restrict__ A4ptr = reinterpret_cast<const float4*>(A + (int64_t)m * K);
        const float4* __restrict__ B4ptr = reinterpret_cast<const float4*>(B);
        float sum0 = 0.0f, sum1 = 0.0f, sum2 = 0.0f, sum3 = 0.0f;
        int i = tid;
        int stride4 = nthreads * 4;
        for (; i + 3 * nthreads < K4; i += stride4) {
            float4 a0 = __ldcs(&A4ptr[i]);
            float4 b0 = __ldg(&B4ptr[i]);
            sum0 += a0.x * b0.x + a0.y * b0.y + a0.z * b0.z + a0.w * b0.w;
            float4 a1 = __ldcs(&A4ptr[i + nthreads]);
            float4 b1 = __ldg(&B4ptr[i + nthreads]);
            sum1 += a1.x * b1.x + a1.y * b1.y + a1.z * b1.z + a1.w * b1.w;
            float4 a2 = __ldcs(&A4ptr[i + 2 * nthreads]);
            float4 b2 = __ldg(&B4ptr[i + 2 * nthreads]);
            sum2 += a2.x * b2.x + a2.y * b2.y + a2.z * b2.z + a2.w * b2.w;
            float4 a3 = __ldcs(&A4ptr[i + 3 * nthreads]);
            float4 b3 = __ldg(&B4ptr[i + 3 * nthreads]);
            sum3 += a3.x * b3.x + a3.y * b3.y + a3.z * b3.z + a3.w * b3.w;
        }
        for (; i < K4; i += nthreads) {
            float4 a = __ldcs(&A4ptr[i]);
            float4 b = __ldg(&B4ptr[i]);
            sum0 += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
        }
        float sum = sum0 + sum1 + sum2 + sum3;
        // Warp-level reduction
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }
        __shared__ float warp_sums[32];
        int lane = tid & 31;
        int warp_id = tid >> 5;
        if (lane == 0) warp_sums[warp_id] = sum;
        __syncthreads();
        int num_warps = (nthreads + 31) / 32;
        if (warp_id == 0) {
            float val = (lane < num_warps) ? warp_sums[lane] : 0.0f;
            #pragma unroll
            for (int offset = 16; offset > 0; offset >>= 1) {
                val += __shfl_down_sync(0xffffffff, val, offset);
            }
            if (lane == 0) {
                C[m] = val;
            }
        }
        __syncthreads();
    }
}

// Fallback scalar kernel (used only if K is not divisible by 4)
template <typename T>
__global__ void matvec_kernel_scalar(
    const T* __restrict__ A,
    const T* __restrict__ B,
    T* __restrict__ C,
    int M, int K)
{
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    for (int m = blockIdx.x; m < M; m += gridDim.x) {
        Tensor gA = make_tensor(make_gmem_ptr(A + (int64_t)m * K), make_shape(K), make_stride(Int<1>{}));
        Tensor gB = make_tensor(make_gmem_ptr(B), make_shape(K), make_stride(Int<1>{}));
        float sum = 0.0f;
        for (int i = tid; i < K; i += nthreads) {
            sum += gA(i) * gB(i);
        }
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }
        __shared__ float warp_sums[32];
        int lane = tid & 31;
        int warp_id = tid >> 5;
        if (lane == 0) warp_sums[warp_id] = sum;
        __syncthreads();
        int num_warps = (nthreads + 31) / 32;
        if (warp_id == 0) {
            float val = (lane < num_warps) ? warp_sums[lane] : 0.0f;
            #pragma unroll
            for (int offset = 16; offset > 0; offset >>= 1) {
                val += __shfl_down_sync(0xffffffff, val, offset);
            }
            if (lane == 0) {
                C[m] = val;
            }
        }
        __syncthreads();
    }
}

torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
    TORCH_CHECK(B.dim() == 2, "B must be 2D (K, 1)");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");

    int64_t M = A.size(0);
    int64_t K = A.size(1);
    TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(1)");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K, 1)");

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    auto C = torch::empty({M, 1}, A.options());

    const float* ptrA = A_c.data_ptr<float>();
    const float* ptrB = B_c.data_ptr<float>();
    float* ptrC = C.data_ptr<float>();

    int threads = 256;
    int device = 0;
    cudaGetDevice(&device);
    int numSMs = 1;
    cudaDeviceGetAttribute(&numSMs, cudaDevAttrMultiProcessorCount, device);
    bool use_vec4 = (K % 4) == 0;
    // Determine how many blocks can be resident per SM so we can launch a
    // grid size that is an exact multiple of a "full wave" (numSMs *
    // blocksPerSM). The kernel already contains a grid-stride loop over
    // rows (m += gridDim.x), so rounding the grid size up to a full wave
    // avoids a partially-filled tail wave (which otherwise leaves some SMs
    // idle while others finish the last, uneven wave) without changing any
    // kernel semantics.
    int blocksPerSM = 1;
    if (use_vec4) {
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocksPerSM, matvec_kernel_vec4<float>, threads, 0);
    } else {
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocksPerSM, matvec_kernel_scalar<float>, threads, 0);
    }
    if (blocksPerSM < 1) blocksPerSM = 1;
    int full_wave = numSMs * blocksPerSM;
    int grid_size = (int)M;
    if (grid_size < 1) grid_size = 1;
    if (full_wave > 0 && grid_size > full_wave) {
        int waves = (grid_size + full_wave - 1) / full_wave;
        grid_size = waves * full_wave;
    }
    dim3 block((unsigned)threads);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    if (use_vec4) {
        matvec_kernel_vec4<float><<<grid_size, block, 0, stream>>>(
            ptrA, ptrB, ptrC, (int)M, (int)K);
    } else {
        matvec_kernel_scalar<float><<<grid_size, block, 0, stream>>>(
            ptrA, ptrB, ptrC, (int)M, (int)K);
    }

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ", cudaGetErrorString(err));

    return C;
}
"""

matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["matvec_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs matrix-vector multiplication (C = A * B)
    using a custom CuTe-based CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matvec_forward(A.contiguous(), B.contiguous())

